import{_ as r,l as c,o as a,c as i,v as o,p as l,x as t,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"环形缓冲","description":"","frontmatter":{"title":"环形缓冲","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ring-buffer.md","filePath":"cs/ring-buffer.md","lastUpdated":1789023840000}'),h={name:"cs/ring-buffer.md"};function u(f,e,_,m,A,T){const d=c("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="环形缓冲" tabindex="-1">环形缓冲 <a class="header-anchor" href="#环形缓冲" aria-label="Permalink to &quot;环形缓冲&quot;">​</a></h1><div class="epigraph"><p>头尾在定长数组上取模前进，物理上不必搬元素；满与空用计数或浪费一槽来区分。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1 整理</footer></div><p><a href="/cs/deque">上一课</a>允许两端操作，并指出数组表示要用头尾下标绕回。<a href="/cs/queue-buffer">队列与缓冲</a>已把环形当作实现细节提过。本课不重讲 FIFO 合同。缺口是把环写成一等表示：固定 <code>cap</code>、模算术、满空判别，以及为何它是生产者-消费者与 DMA 描述符环的默认布局。摊还扩容仍留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>队列用动态数组在队头 <code>pop</code> 若每次把剩余元素左移，是 \\(\\Theta(n)\\)。把头指针前移则留下空洞。缺口是<strong>逻辑下标对 <code>cap</code> 取模</strong>：物理槽循环使用，元素只在 enqueue/dequeue 时写一次。容量用尽不在本课倍增——有界缓冲把背压写成「满则失败或等待」。</p><p><code>head==tail</code> 既像空又像满。必须另用 <code>count</code>，或规定「满时浪费一槽」使满为 <code>(tail+1)%cap==head</code>。</p><p><span class="marginnote">硬件环形缓冲与软件相同：指针前进、环绕。流水线寄存器链是深度固定、不能绕回的退化环。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>槽 <code>a[0..cap)</code>。入队写 <code>a[tail]</code>，<code>tail=(tail+1)%cap</code>。出队读 <code>a[head]</code>，<code>head=(head+1)%cap</code>。deque 的另一端对称。合法元素是从 <code>head</code> 走 <code>count</code> 步，不要扫整表。</p>',9)),(a(),l(p,null,{default:t(()=>[s(d,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22head%22%5D%20--%3E%20A%5B%22%E5%8D%A0%E7%94%A8%E6%AE%B5%22%5D%0A%20%20A%20--%3E%20T%5B%22tail%22%5D%0A%20%20T%20--%3E%20F%5B%22%E7%A9%BA%E9%97%B2%E6%AE%B5%22%5D%0A%20%20F%20--%3E%20H%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>无锁单生产单消费可以用独立的 head/tail 与内存序；本课只点名，不写 fence——那是体系结构栏的 TSO 课已经备过的对象，这里不把并发做成主干。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>顺序走环，空间局部性好，直到绕回边界：那一次访问从高地址跳到 <code>a[0]</code>，可能换页、换 cache 行集合。比链表仍稳。定容使实时系统最坏 \\(\\Theta(1)\\)，没有动态数组那次线性复制。</p><p>与动态数组：环不改基址，已取出的指针若指向槽会在复用后别名——合同应禁止握着已出队槽。动态数组改基址，失效模式不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明摊还，不把 <code>cap</code> 倍增写进环的热路径。需要无界增长时，下一课用表扩张分析，或用链表。也不把优先队列塞进环：那按键不按到达序。</p><p>后课默认：有界 FIFO/deque 的高性能表示是环形数组。偶发线性复制的平均代价，用摊还语言说。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>头尾取模，元素不搬；满空靠计数或浪费一槽。</li><li>定容最坏 \\(\\Theta(1)\\)，绕回仍比链表连续。</li><li>倍增复制的平均账是下一课摊还。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1 循环表与队列表示。</li></ul>',9))])}const E=r(h,[["render",u]]);export{b as __pageData,E as default};
